def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    # Uniform horizontal stripes are samples from a repeating row sequence.
    if all(len(set(row)) == 1 for row in grid):
        samples = [(r, row[0]) for r, row in enumerate(grid) if row[0] != 0]
        if samples:
            # The code presents one stripe sample per sequence slot. Choose
            # that cycle length, then align slots by their row coordinates.
            period = len(samples)
            phase = {}
            valid = True
            for r, color in samples:
                residue = r % period
                if residue in phase and phase[residue] != color:
                    valid = False
                    break
                phase[residue] = color
            if valid:
                for residue in range(period):
                    if residue not in phase:
                        distance = next(d for d in range(1, period + 1)
                                        if (residue - d) % period in phase)
                        phase[residue] = phase[(residue - distance) % period]
                return [[phase[r % period] for _ in range(w)] for r in range(h)]

    # Diagonal examples encode each color on a repeating (row-column) class.
    for period in range(1, max(h, w) + 1):
        phase = {}
        valid = True
        for r, row in enumerate(grid):
            for c, color in enumerate(row):
                if color == 0:
                    continue
                residue = (r - c) % period
                if residue in phase and phase[residue] != color:
                    valid = False
                    break
                phase[residue] = color
            if not valid:
                break
        if valid and phase:
            for residue in range(period):
                if residue not in phase:
                    distance = next(d for d in range(1, period + 1)
                                    if (residue - d) % period in phase)
                    phase[residue] = phase[(residue - distance) % period]
            return [[phase[(r - c) % period] for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]

